//! Exact-token and numerical qualification for EmbeddingGemma 2 results.
//! Passing this check means numerical agreement with a *provided* reference,
//! NOT independently authenticated Google parity or validated SM61 execution.
use anyhow::{ensure, Result};
use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize)]
pub struct ObservedEmbedding {
    pub architecture: String,
    pub dtype: String,
    pub dimensions: usize,
    pub token_count: usize,
    pub token_ids: Vec<u32>,
    pub vector: Vec<f32>,
}

/// Reference generated by an independently pinned implementation, with the
/// revision and prompt policy preserved by the experimenter.
#[derive(Debug, Deserialize)]
pub struct ReferenceEmbedding {
    pub schema_version: u32,
    pub model_revision: String,
    pub tokenizer_revision: String,
    pub prompt_policy: String,
    pub dimensions: usize,
    pub token_ids: Vec<u32>,
    pub vector: Vec<f32>,
}

#[derive(Debug, Serialize)]
pub struct ParityReport {
    pub outcome: &'static str,
    pub comparison: &'static str,
    pub reference_model_revision: String,
    pub reference_tokenizer_revision: String,
    pub prompt_policy: String,
    pub dimensions: usize,
    pub tokens: usize,
    pub reference_l2: f64,
    pub observed_l2: f64,
    pub cosine_similarity: f64,
    pub max_abs_error: f64,
    pub mean_abs_error: f64,
    pub minimum_cosine: f64,
    pub maximum_abs_error: f64,
    pub reference_origin_independently_verified: bool,
}

pub fn compare(
    observed: &ObservedEmbedding,
    reference: &ReferenceEmbedding,
    min_cosine: f64,
    max_abs_allowed: f64,
) -> Result<ParityReport> {
    ensure!(
        reference.schema_version == 1,
        "reference schema_version must be 1"
    );
    ensure!(
        !reference.model_revision.trim().is_empty()
            && !reference.tokenizer_revision.trim().is_empty()
            && !reference.prompt_policy.trim().is_empty(),
        "reference must record pinned model/tokenizer revisions and prompt policy"
    );
    ensure!(
        min_cosine.is_finite() && (0.0..=1.0).contains(&min_cosine),
        "min_cosine outside [0,1]"
    );
    ensure!(
        max_abs_allowed.is_finite() && max_abs_allowed >= 0.0,
        "invalid max_abs_allowed"
    );
    ensure!(
        observed.architecture == "EmbeddingGemma2Model" && observed.dtype == "f32",
        "wrong model architecture or dtype"
    );
    ensure!(
        super::SUPPORTED_DIMENSIONS.contains(&observed.dimensions),
        "unsupported Matryoshka dimension"
    );
    ensure!(
        observed.dimensions == reference.dimensions
            && observed.vector.len() == observed.dimensions
            && reference.vector.len() == reference.dimensions,
        "embedding shape mismatch"
    );
    ensure!(
        !reference.token_ids.is_empty()
            && reference.token_ids.len() <= super::MAX_TOKENS
            && reference.token_ids == observed.token_ids
            && observed.token_count == observed.token_ids.len(),
        "token IDs or token count differ from reference"
    );
    ensure!(
        reference
            .vector
            .iter()
            .chain(observed.vector.iter())
            .all(|x| x.is_finite()),
        "non-finite embedding component"
    );
    let mut observed_sq = 0_f64;
    let mut reference_sq = 0_f64;
    let mut dot = 0_f64;
    let mut max_abs = 0_f64;
    let mut abs_sum = 0_f64;
    for (&a, &b) in observed.vector.iter().zip(&reference.vector) {
        let a = f64::from(a);
        let b = f64::from(b);
        observed_sq += a * a;
        reference_sq += b * b;
        dot += a * b;
        let difference = (a - b).abs();
        max_abs = max_abs.max(difference);
        abs_sum += difference;
    }
    let observed_l2 = observed_sq.sqrt();
    let reference_l2 = reference_sq.sqrt();
    ensure!(
        observed_l2.is_finite()
            && reference_l2.is_finite()
            && (observed_l2 - 1.0).abs() <= 0.01
            && (reference_l2 - 1.0).abs() <= 0.01,
        "embeddings are not unit-normalized (Matryoshka vectors must be normalized)"
    );
    let cosine_similarity = dot / (observed_l2 * reference_l2);
    ensure!(
        cosine_similarity >= min_cosine,
        "cosine similarity {cosine_similarity:.8} below minimum {min_cosine:.8}"
    );
    ensure!(
        max_abs <= max_abs_allowed,
        "max abs error {max_abs:.8} above threshold {max_abs_allowed:.8}"
    );
    Ok(ParityReport {
        outcome: "NUMERICAL_MATCH",
        comparison: "user_supplied_reference_only",
        reference_model_revision: reference.model_revision.clone(),
        reference_tokenizer_revision: reference.tokenizer_revision.clone(),
        prompt_policy: reference.prompt_policy.clone(),
        dimensions: observed.dimensions,
        tokens: observed.token_count,
        reference_l2,
        observed_l2,
        cosine_similarity,
        max_abs_error: max_abs,
        mean_abs_error: abs_sum / observed.dimensions as f64,
        minimum_cosine: min_cosine,
        maximum_abs_error: max_abs_allowed,
        reference_origin_independently_verified: false,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixture() -> (ObservedEmbedding, ReferenceEmbedding) {
        let mut vector = vec![0.0f32; 128];
        vector[0] = 1.0;
        (
            ObservedEmbedding {
                architecture: "EmbeddingGemma2Model".into(),
                dtype: "f32".into(),
                dimensions: 128,
                token_count: 3,
                token_ids: vec![1, 2, 3],
                vector: vector.clone(),
            },
            ReferenceEmbedding {
                schema_version: 1,
                model_revision: "example-pinned-revision".into(),
                tokenizer_revision: "example-pinned-revision".into(),
                prompt_policy: "document".into(),
                dimensions: 128,
                token_ids: vec![1, 2, 3],
                vector,
            },
        )
    }

    #[test]
    fn identical_vectors_pass_but_do_not_authenticate_origin() {
        let (observed, reference) = fixture();
        let report = compare(&observed, &reference, 0.999, 0.01).unwrap();
        assert_eq!(report.outcome, "NUMERICAL_MATCH");
        assert!(!report.reference_origin_independently_verified);
    }

    #[test]
    fn token_mismatch_fails_even_when_vectors_match() {
        let (observed, mut reference) = fixture();
        reference.token_ids[0] = 987;
        assert!(compare(&observed, &reference, 0.999, 0.01).is_err());
    }

    #[test]
    fn shape_and_nonfinite_values_are_rejected() {
        let (observed, mut reference) = fixture();
        reference.dimensions = 256;
        assert!(compare(&observed, &reference, 0.999, 0.01).is_err());
        reference.dimensions = 128;
        reference.vector[2] = f32::NAN;
        assert!(compare(&observed, &reference, 0.999, 0.01).is_err());
    }

    #[test]
    fn numeric_mismatch_fails() {
        let (observed, mut reference) = fixture();
        reference.vector[0] = 0.0;
        reference.vector[1] = 1.0;
        assert!(compare(&observed, &reference, 0.999, 0.01).is_err());
    }
}
